      if (array == null || array.size() == 0) {
        return "";
      }
      if (join == null) {
        join="";
      }
      StringBuilder ret=new StringBuilder();
      int count=0;
      Iterator<String> iterator=array.iterator();
      while (iterator.hasNext()) {
